+     let mut queue = task::spawn(DelayQueue::new());
+     let last = queue.insert("last", ms(100));
+     let other = queue.insert("other", ms(200));
+ 
+     assert_pending!(poll!(queue));
+     assert!(!queue.is_woken());
+ 
+     assert_eq!(queue.remove(&other).into_inner(), "other");
+     assert!(!queue.is_woken());
+ 
+     assert_eq!(queue.remove(&last).into_inner(), "last");
+     assert!(queue.is_woken());
+     assert!(queue.is_empty());
+     assert!(assert_ready!(poll!(queue)).is_none());
+ }
+ 
+ #[tokio::test(start_paused = true)]
+ async fn try_remove_last_entry_wakes() {
+     let mut queue = task::spawn(DelayQueue::new());
+     let last = queue.insert("last", ms(100));
+     let other = queue.insert("other", ms(200));
+ 
+     assert_pending!(poll!(queue));
+     assert!(!queue.is_woken());
+ 
+     assert_eq!(queue.try_remove(&other).unwrap().into_inner(), "other");
+     assert!(!queue.is_woken());
+ 
+     assert!(queue.try_remove(&other).is_none());
+     assert!(!queue.is_woken());
+ 
+     assert_eq!(queue.try_remove(&last).unwrap().into_inner(), "last");
+     assert!(queue.is_woken());
+     assert!(queue.is_empty());
+     assert!(assert_ready!(poll!(queue)).is_none());
+ 
+     assert!(queue.try_remove(&last).is_none());
+     assert!(!queue.is_woken());
+ }
